import type {
  UCATChartVisual,
  UCATQuestion,
  UCATQuestionTag,
} from "./ucatQuestionBank";

export type QrCuratedInput =
  | {
      kind: "single";
      subtype:
        | "qr-graphs"
        | "qr-percentages"
        | "qr-rates-ratios"
        | "qr-averages"
        | "qr-units-geometry"
        | "qr-estimation";
      tags?: UCATQuestionTag[];
      leftTitle?: string;
      stimulus: string[];
      visual?: UCATChartVisual;
      question: string;
      correct: string;
      distractors: [string, string, string];
      explanation: string;
    }
  | {
      kind: "set";
      setId: string;
      stimulus: string[];
      visual: UCATChartVisual;
      questions: Array<{
        subtype:
          | "qr-graphs"
          | "qr-percentages"
          | "qr-rates-ratios"
          | "qr-averages"
          | "qr-units-geometry"
          | "qr-estimation";
        tags?: UCATQuestionTag[];
        question: string;
        correct: string;
        distractors: [string, string, string];
        explanation: string;
      }>;
    };

